INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (1, 0, 1, 'OpenSSH Remote Code Execution (regreSSHion)', 'QUALYS-377399', 'CVE-2024-6387', 105, 5, 8.1, 1, 0, 'Exploit-DB, GitHub PoC', 'Remote Code Execution', 1, '2024-07-01', 'A signal handler race condition in OpenSSH sshd allows unauthenticated remote attackers to execute arbitrary code with root privileges on glibc-based Linux systems.', 'Attackers can exploit the race condition during asynchronous SIGALRM timeout handling to hijack execution flow and obtain an unauthenticated root shell.', 'Complete compromise of the underlying host, root privilege escalation, credential theft, and unauthorized lateral movement across the internal subnet.', 'Upgrade OpenSSH to version 9.8p1 or newer. Workaround: Set ''LoginGraceTime 0'' in /etc/ssh/sshd_config (note: disables timeout and may expose to DoS).', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (2, 0, 1, 'Apache Log4j JNDI Remote Code Execution (Log4Shell)', 'QUALYS-376157', 'CVE-2021-44228', 103, 5, 10.0, 3, 1, 'Metasploit, Core Impact, Exploit-DB, CISA KEV', 'Remote Code Execution', 1, '2021-12-10', 'Apache Log4j2 versions 2.0-beta9 through 2.14.1 JNDI features used in configuration, log messages, and parameters do not protect against attacker-controlled LDAP and other JNDI related endpoints.', 'An unauthenticated remote attacker can submit a crafted string containing ''${jndi:ldap://...}'' in HTTP headers, parameters, or forms, forcing the vulnerable server to load and execute malicious arbitrary Java byte code.', 'Full takeover of the application server container, shell access, exfiltration of environment variables, secrets, and database credentials.', 'Upgrade Log4j to 2.17.1 or higher. Immediate workaround: set system property ''log4j2.formatMsgNoLookups=true'' or remove JndiLookup.class from log4j-core JAR.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (3, 0, 1, 'Spring Framework Remote Code Execution (Spring4Shell)', 'QUALYS-376527', 'CVE-2022-22965', 102, 5, 9.8, 2, 1, 'Metasploit, Exploit-DB, CISA KEV', 'Remote Code Execution', 1, '2022-03-31', 'A Spring MVC or Spring WebFlux application running on JDK 9+ may be vulnerable to remote code execution via data binding when packaged as a traditional WAR deployed to an Apache Tomcat servlet container.', 'Attackers manipulate ClassLoader properties via request parameter binding to modify Tomcat AccessLogValve patterns, writing a web shell directly to disk.', 'Persistent backdoor installation, remote arbitrary code execution, and data compromise.', 'Upgrade Spring Framework to version 5.3.18 / 6.0 or higher. Upgrade Tomcat to latest maintenance release.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (4, 0, 1, 'HTTP/2 Rapid Reset Denial of Service', 'QUALYS-377701', 'CVE-2023-44487', 104, 4, 7.5, 3, 1, 'In The Wild DDoS scripts, CISA KEV', 'Denial of Service', 1, '2023-10-10', 'The HTTP/2 protocol allows a denial of service (server resource consumption) because request cancellation can reset many streams rapidly without the server being able to enforce rate limits.', 'A single client can send high volumes of RST_STREAM frames immediately following HEADERS frames, exhausting server CPU and memory resources.', 'Service degradation or complete unavailability for legitimate users across public web services.', 'Apply vendor security updates to Nginx (1.25.3 / 1.24.1+), Apache HTTP Server, or cloud load balancers; configure HTTP/2 stream limiters.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (5, 0, 1, 'OpenSSL X.509 Email Address Buffer Overflow', 'QUALYS-376911', 'CVE-2022-3602', 106, 4, 7.5, 0, 0, 'None', 'Memory Corruption / RCE', 1, '2022-11-01', 'A 4-byte stack buffer overflow can occur in OpenSSL during X.509 certificate verification, specifically in name constraint checking of email addresses.', 'Maliciously crafted TLS client certificates containing punycode email addresses can trigger stack buffer corruption during TLS handshake verification.', 'Denial of service (crash) or potential arbitrary code execution under specific compiler stack layouts.', 'Upgrade OpenSSL to version 3.0.7 or later (or 1.1.1s for 1.1.1 series).', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (6, 0, 1, 'Jenkins CLI Arbitrary File Read Vulnerability', 'QUALYS-377450', 'CVE-2024-23897', 112, 5, 9.8, 2, 1, 'Metasploit, Exploit-DB, CISA KEV', 'Information Disclosure / RCE', 1, '2024-01-24', 'Jenkins uses the args4j library to parse command arguments on the Jenkins controller. This parser features ''@'' character argument expansion which replaces ''@'' followed by a file path with file contents.', 'Unauthenticated attackers with read access can read the first few lines of arbitrary files on the Jenkins controller filesystem, or full files with admin privileges, enabling cryptographic key extraction and full RCE.', 'Extraction of credentials, encryption master keys, source code, and potential elevation to full controller remote execution.', 'Upgrade Jenkins core to 2.442 or LTS 2.426.3. Immediate workaround: disable CLI access via script console.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (7, 0, 1, 'Apache Spark Command Injection via ACL', 'QUALYS-376689', 'CVE-2022-33891', 110, 4, 8.8, 1, 0, 'GitHub PoC, Nuclei', 'Command Injection', 1, '2022-07-18', 'Apache Spark UI enables ACLs via ''spark.acls.enable''. With an improper configuration, a bash command is executed through Unix shell for user authentication with arbitrarily supplied user input.', 'Attackers can supply arbitrary shell commands within the ''?doAs='' HTTP query parameter when accessing the Spark Web UI.', 'Remote shell execution under the spark system user account on the master node.', 'Upgrade Apache Spark to 3.2.2, 3.3.0, or newer.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (8, 0, 1, 'Apache HTTP Server Path Traversal & Remote Code Execution', 'QUALYS-376044', 'CVE-2021-41773', 111, 4, 7.5, 2, 1, 'Metasploit, Exploit-DB, CISA KEV', 'Path Traversal / RCE', 1, '2021-10-05', 'A flaw was found in a change made to path normalization in Apache HTTP Server 2.4.49. An attacker could use a path traversal attack to map URLs to files outside the directories configured by Alias-like directives.', 'If files outside of document roots are not protected by ''require all denied'' and mod_cgi is enabled, path traversal triggers arbitrary CGI script execution.', 'Arbitrary file disclosure (e.g., /etc/passwd) and execution of system commands.', 'Upgrade Apache HTTP Server to version 2.4.51 or higher.', 0, NOW(), NOW());
INSERT INTO `glpi_plugin_vulnerabilitymanagement_vulnerabilities` (`id`, `entities_id`, `is_recursive`, `name`, `vuln_code`, `cve`, `softwares_id`, `severity`, `cvss_score`, `exploit_status`, `cisa_kev`, `exploit_frameworks`, `category`, `is_patchable`, `published_date`, `description`, `threat`, `impact`, `solution`, `is_deleted`, `date_creation`, `date_mod`) VALUES (9, 0, 1, 'Node.js Prototype Pollution in Core Stream APIs', 'QUALYS-377120', 'CVE-2023-30533', 113, 3, 6.5, 0, 0, 'None', 'Prototype Pollution', 1, '2023-06-20', 'Node.js contains a prototype pollution vulnerability in stream processing when untrusted user input is passed without sanitization into internal object properties.', 'Attackers can manipulate JavaScript Object prototypes leading to unexpected logic bypass or application crash.', 'Service disruption and potential authentication bypass depending on application property lookups.', 'Upgrade Node.js to 16.20.1, 18.16.1, or 20.3.1.', 0, NOW(), NOW());
